export function DashboardLandingPage() {
  const { isAuthenticated, user } = useAuth();
  const [, setLocation] = useLocation();
  const profile = trpc.arenaHub.profile.mine.useQuery(undefined, { enabled: isAuthenticated && user?.role !== "admin" });
  const destination = dashboardDestination(user?.role, profile.data?.role);

  useEffect(() => {
    if (isAuthenticated && (user?.role === "admin" || !profile.isLoading)) setLocation(destination);
  }, [destination, isAuthenticated, profile.isLoading, setLocation, user?.role]);

  return <main className="app-shell inner-shell"><Atmosphere /><section className="role-activation"><div><p className="eyebrow">ACCOUNT WORKSPACE</p><h1>Opening your <em>dashboard.</em></h1><p>Your account is being routed to the appropriate ArenaHub workspace.</p></div></section></main>;
}

