function Atmosphere() { return <><div className="atmosphere-orb atmosphere-orb-one" /><div className="atmosphere-orb atmosphere-orb-two" /><div className="grid-fade" /></>; }
function BrandMark() { return <span className="brand-mark" aria-hidden="true"><span /><span /><span /></span>; }

export function PublicNav() {
  const { isAuthenticated, user, logout } = useAuth();
  const profile = trpc.arenaHub.profile.mine.useQuery(undefined, { enabled: isAuthenticated && user?.role !== "admin" });
  const accountPath = user?.role === "admin" ? "/admin/dashboard" : profile.data?.role === "OWNER" ? "/owner/dashboard" : "/player/dashboard";
  const roleIdentity = getRoleIdentity(user?.role === "admin" ? "ADMIN" : profile.data?.role);
  return <header className="public-nav"><Link href="/" className="brand"><BrandMark /><span>ARENA<span className="brand-accent">HUB</span></span></Link><nav><Link href="/discover">Discover</Link><Link href="/owner">For owners</Link>{isAuthenticated && <Link href="/owner/edit">Edit venue</Link>}<Link href="/how-it-works">How it works</Link></nav><div className="nav-actions">{isAuthenticated ? <>{roleIdentity && <span className={`role-identity role-identity-${roleIdentity.tone}`}><span aria-hidden="true" />{roleIdentity.label}</span>}<Link href={accountPath}><Button variant="ghost" className="nav-account"><CircleUserRound />Workspace</Button></Link><Button variant="outline" className="nav-logout" onClick={logout}>Sign out</Button></> : <><Button variant="ghost" onClick={() => startLogin()}>Sign in</Button><Link href="/join"><Button className="button-copper">Join ArenaHub <ArrowRight /></Button></Link></>}</div></header>;
}

function SearchPanel({ compact = false }: { compact?: boolean }) {
  const [, setLocation] = useLocation(); const [sport, setSport] = useState("all"); const [city, setCity] = useState("");
  function submit(event: FormEvent) { event.preventDefault(); const query = new URLSearchParams(); if (sport !== "all") query.set("sport", sport); if (city.trim()) query.set("city", city.trim()); setLocation(`/discover?${query.toString()}`); }
  return <form onSubmit={submit} className={`search-panel ${compact ? "search-panel-compact" : ""}`}><div className="search-field"><MapPinned /><div><label htmlFor="city">Location</label><Input id="city" value={city} onChange={event => setCity(event.target.value)} placeholder="City or neighbourhood" /></div></div><div className="search-field"><Trophy /><div><label>Sport</label><Select value={sport} onValueChange={setSport}><SelectTrigger aria-label="Choose sport"><SelectValue placeholder="Any sport" /></SelectTrigger><SelectContent><SelectItem value="all">Any sport</SelectItem>{sports.map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div></div><Button type="submit" className="button-copper search-action"><Search />Find arenas</Button></form>;
}

