export function JoinArenaHubPage() {
  const { isAuthenticated } = useAuth();
  const [, setLocation] = useLocation();
  const selected = new URLSearchParams(window.location.search).get("role")?.toUpperCase();
  const selectedRole = selected === "PLAYER" || selected === "OWNER" || selected === "ADMIN" ? selected as SignupRole : undefined;

  useEffect(() => {
    if (isAuthenticated && selectedRole) setLocation(signupDestination(selectedRole));
  }, [isAuthenticated, selectedRole, setLocation]);

  function begin(role: SignupRole) {
    if (!isAuthenticated) {
      startLogin(signupReturnPath(role));
      return;
    }
    setLocation(signupDestination(role));
  }

  return <main className="app-shell inner-shell"><Atmosphere /><PublicNav /><section className="join-heading"><p className="eyebrow">CHOOSE YOUR ARENAHUB PATH</p><h1>Start with the role<br /><em>that fits your game.</em></h1><p>Players and arena owners can create their platform profiles after sign-in. Administrator access is provisioned separately and is never granted by selecting a card.</p></section><section className="signup-role-grid">{signupChoices.map(choice => { const Icon = choice.icon; const protectedRole = !isSelfServiceSignupRole(choice.role); return <article className={selectedRole === choice.role ? "signup-role-card selected" : "signup-role-card"} key={choice.role}><div className="signup-role-icon"><Icon /></div><p className="eyebrow">{choice.eyebrow}</p><h2>{choice.title}</h2><p>{choice.copy}</p>{protectedRole && <small><ShieldCheck /> Administrator role selection does not create approval authority.</small>}<Button className={choice.role === "OWNER" ? "button-copper" : ""} variant={choice.role === "OWNER" ? "default" : "outline"} onClick={() => begin(choice.role)}>{choice.action} <ArrowRight /></Button></article>; })}</section></main>;
}

