export function OwnerPortalPage() {
  const { isAuthenticated, user } = useAuth(); const [, setLocation] = useLocation(); const profile = trpc.arenaHub.profile.mine.useQuery(undefined, { enabled: isAuthenticated && user?.role !== "admin" }); const chooseRole = trpc.arenaHub.profile.chooseRole.useMutation({ onSuccess: () => { profile.refetch(); setLocation("/owner/dashboard"); } }); const [name, setName] = useState(""); const isOwner = profile.data?.role === "OWNER";
  return <main className="app-shell inner-shell"><Atmosphere /><PublicNav /><section className="owner-hero"><div><p className="eyebrow">OWNER CONTROL ROOM</p><h1>Run your venue<br /><em>your way.</em></h1><p>A structured publishing pathway for genuine operators: provide details, submit documentation, add facilities, and wait for approval before you appear in discovery.</p></div><div className="owner-steps"><Step count="01" title="Establish ownership" copy="Select the owner role and complete your profile." active={isOwner} /><Step count="02" title="Submit your arena" copy="Add a real venue, courts, equipment, and location." active={false} /><Step count="03" title="Pass the review" copy="An administrator verifies the claim before discovery." active={false} /></div></section>{!isAuthenticated ? <Gate icon={<ShieldCheck />} title="Sign in to establish a venue." copy="Owner tools are protected and unavailable to players until an owner profile is selected." /> : user?.role === "admin" ? <section className="role-activation"><div><p className="eyebrow">ADMINISTRATOR BOUNDARY</p><h2>Administrator accounts cannot manage arenas.</h2><p>For role separation, this administrator email cannot activate an Arena Owner profile. Use the restricted administrator workspace to review submissions.</p></div><Link href="/admin/dashboard"><Button className="button-copper">Open administrator workspace</Button></Link></section> : profile.data?.role === "PLAYER" ? <section className="role-activation"><div><p className="eyebrow">ARENA SUBMISSION</p><h2>This email is a Player account.</h2><p>For account separation, a Player profile cannot submit or manage arenas. Use a different email address for an Arena Owner account.</p></div><Link href="/player/dashboard"><Button className="button-copper">Open player workspace</Button></Link></section> : !isOwner ? <section className="role-activation"><div><p className="eyebrow">ACTIVATE OWNER MODE</p><h2>Are you responsible for a real sports venue?</h2><p>Create an Arena Owner profile to begin the private submission and verification workflow. The platform never publishes owner listings automatically.</p></div><form onSubmit={event => { event.preventDefault(); chooseRole.mutate({ role:"OWNER", displayName:name }); }}><Input value={name} onChange={event => setName(event.target.value)} placeholder="Your full name" required minLength={2} /><Button type="submit" className="button-copper" disabled={chooseRole.isPending}>Activate owner profile <ArrowRight /></Button>{chooseRole.error && <p className="form-error">{chooseRole.error.message}</p>}</form></section> : <OwnerDashboard />}</main>;
}

